function errorMessage(e){if(e.name==='TimeoutError'||e.name==='TypeError')return 'No pudimos conectar con el servidor. Comprueba tu conexión y vuelve a intentar.';if(e.code==='PGRST205'||e.code==='42883'||e.code==='42P01')return 'Falta instalar la configuración de este módulo en Supabase. Los datos no se guardaron.';if(e.message?.includes('Invalid login'))return 'El correo o la contraseña no coinciden.';if(e.message?.includes('Email not confirmed'))return 'Confirma tu correo antes de entrar.';if(e.code==='user_already_exists'||e.message?.includes('already registered'))return 'Ya existe una cuenta con ese correo. Inicia sesión o recupera tu contraseña.';if(e.code==='weak_password'||e.message?.includes('Password should'))return 'La contraseña es muy débil. Usa al menos 8 caracteres y combina letras y números.';if(e.code==='same_password')return 'La nueva contraseña debe ser distinta a la anterior.';if(e.code==='over_email_send_rate_limit'||e.status===429)return 'Hiciste varios intentos seguidos. Espera unos minutos y vuelve a intentar.';return e.message||'No pudimos completar la operación. Intenta otra vez.'}
async function request(path,options={}){
 if(S.session?.portal_expires_at&&S.session.portal_expires_at<=Date.now()){saveSession(null);S.user=null;S.staff=null;S.permissions=[];S.route='login';throw new Error('Tu sesión de 5 días terminó. Vuelve a iniciar sesión.')}
 if(S.session?.expires_at&&S.session.expires_at*1000<Date.now()+30000)await refresh();
 const headers={apikey:KEY,Authorization:`Bearer ${S.session?.access_token||KEY}`,...options.headers};
 if(options.body&&!(options.body instanceof Blob)){headers['Content-Type']='application/json'}
 const r=await fetch(URL_API+path,{...options,headers,signal:AbortSignal.timeout(15000)});
 const data=await r.json().catch(()=>null);if(!r.ok){const e=new Error(data?.message||data?.msg||data?.error_description||data?.error||`Error ${r.status}`);e.code=data?.error_code||data?.code;e.status=r.status;throw e}return data;
}
function saveSession(s){S.session=s;if(s){if(!s.portal_expires_at)s.portal_expires_at=Date.now()+5*24*60*60*1000;localStorage.setItem('134340.session',JSON.stringify(s))}else localStorage.removeItem('134340.session')}
async function refresh(){const portalExpiresAt=S.session?.portal_expires_at;const r=await fetch(URL_API+'/auth/v1/token?grant_type=refresh_token',{signal:AbortSignal.timeout(15000),method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:S.session.refresh_token})});const d=await r.json();if(!r.ok){saveSession(null);throw new Error('Tu sesión venció. Vuelve a iniciar sesión.')}if(portalExpiresAt)d.portal_expires_at=portalExpiresAt;saveSession(d)}
async function get(t,q=''){const all=[];const order=t==='staff_access'?'user_id':t==='staff_permissions'?'user_id,module,action':t==='customer_details'?'customer_id':'id';for(let offset=0;offset<100000;offset+=500){const page=await request(`/rest/v1/${t}?select=*&order=${order}&limit=500&offset=${offset}${q?'&'+q:''}`);all.push(...page);if(page.length<500)return all;}throw new Error('Esta sección necesita paginación adicional para su volumen de datos.');}
const insert=(t,d)=>request('/rest/v1/'+t,{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(d)});
const update=(t,id,d)=>request(`/rest/v1/${t}?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(d)});
const rpc=(n,d)=>n==='claim_legacy_history'?sheetsRequest('claim',{key:d.p_key}):request('/rest/v1/rpc/'+n,{method:'POST',body:JSON.stringify(d)});
function customer(id){return rows('profiles').find(p=>p.id===id)?.customer_code||rows('profiles').find(p=>p.id===id)?.full_name||'Clienta sin código'}
function chargePaid(c){return rows('payments').filter(p=>p.charge_id===c.id&&p.status==='approved').reduce((a,p)=>a+Number(p.amount),0)}
const chargeBalance=c=>Math.max(0,Number(c.amount)-chargePaid(c));
