async function load(){if(S.session?.portal_expires_at&&S.session.portal_expires_at<Date.now()){saveSession(null);S.user=null;S.staff=null;S.route='login';toast('Tu sesión de 5 días terminó. Vuelve a iniciar sesión.')}window.Masterlist?.invalidate();S.busy=true;S.errors=[];render();try{
 if(demo){demoData();return}
 if(S.session){S.user=await request('/auth/v1/user');const [p,st,pm]=await Promise.all([get('profiles','id=eq.'+S.user.id),get('staff_access','user_id=eq.'+S.user.id),get('staff_permissions','user_id=eq.'+S.user.id)]);S.profile=p[0];S.staff=st.find(x=>x.active);S.permissions=pm;}
 else{S.user=null;S.profile=null;S.staff=null;S.permissions=[]}
 const tables=S.user?['products','product_variants','profiles','orders','order_items','charges','payments','shipments','shipment_items','announcements','customer_details','internal_notes',...(isAdmin()?['staff_access','staff_permissions','audit_log']:[])]:[];
 const results=await Promise.allSettled(tables.map(t=>get(t)));S.data={};results.forEach((r,i)=>{if(r.status==='fulfilled')S.data[tables[i]]=r.value;else S.errors.push({table:tables[i],message:errorMessage(r.reason)})});
 if(S.user){await Promise.all([loadImageURLs(),loadSheetsIdentity()]);if(S.route==='history')await loadSheetsHistory();}
 }catch(e){toast(errorMessage(e));if(e.status===401){saveSession(null);S.user=null;S.staff=null;S.route='login'}}finally{S.busy=false;render();if(S.route==='masterlist')openMasterlist();if(S.route==='private-keys'&&S.user&&can('customers')&&!demo)loadPrivateKeys().catch(e=>toast(errorMessage(e)))}}
function navigation(){const links=[['store','Tienda','store']];if(S.user){links.push(['history','Historial anterior','orders'],['dashboard','Mi universo','dashboard'],['orders',isStaff()?'Pedidos':'Mis pedidos','orders'],['payments',isStaff()?'Pagos':'Mis pagos','payments'],['shipments',isStaff()?'Envíos':'Mis envíos','shipments'],['announcements','Avisos','announcements']);if(can('shipments')||can('payments'))links.push(['boxes','Cajas y llegadas','shipments']);if(can('inventory'))links.push(['inventory','Productos e inventario','inventory']);if(can('customers'))links.push(['customers','Clientas','customers'],['private-keys','Claves privadas','customers']);if(isAdmin())links.push(['masterlist','Masterlist completa','masterlist'],['settings','Equipo y permisos','settings']);}return links.filter(([r])=>!isStaff()||!['orders','payments','shipments','announcements'].includes(r)||can(r)).map(([r,l,i])=>`<button data-act="route" data-id="${r}" class="${S.route===r?'active':''}">${ic(i)}${l}</button>`).join('')}
function render(){app.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="/"><img src="/assets/logo.jpg" alt="Logo de 134340"><span><strong>134340</strong><small>YOUR LITTLE UNIVERSE</small></span></a><div class="navlabel">${isStaff()?'ADMINISTRACIÓN':'EXPLORA TU UNIVERSO'}</div><nav class="nav" aria-label="Principal">${navigation()}</nav><div class="sidebar-foot"><div class="mascot-note"><img src="/assets/logo.jpg" alt=""><p><b>Tu V-endedor te acompaña</b></p><small>Cada colección tiene su órbita.</small></div></div></aside><main class="main"><header class="topbar"><span class="breadcrumb">134340 / ${esc({store:'Tienda',dashboard:'Mi universo',orders:'Pedidos',payments:'Pagos',shipments:'Envíos',inventory:'Productos e inventario',customers:'Clientas',announcements:'Avisos',settings:'Equipo y permisos',history:'Historial anterior',boxes:'Cajas y llegadas',masterlist:'Masterlist completa','private-keys':'Claves privadas',login:'Acceso'}[S.route]||'Portal')}</span><div class="actions">${S.user?`<small>${esc(S.profile?.full_name||S.user.email)}</small><span class="avatar">${esc((S.profile?.full_name||S.user.email||'V').slice(0,2).toUpperCase())}</span><button class="btn light sm" data-act="logout" aria-label="Cerrar sesión">${ic('logout')}</button>`:btn('Entrar a mi universo','route','login','soft')}</div></header>${demo?'<div class="preview-banner"><b>Vista de diseño con datos de ejemplo.</b> No muestra ventas reales ni guarda cambios. <a href="/">Ir al portal real</a></div>':''}${S.busy?'<div class="loading"><div class="loader"></div>Preparando tu universo…</div>':content()}<footer class="space-footer">134340 · HECHO PARA ATESORAR LO QUE AMAS</footer></main></div>`}
function pageHead(title,sub,action=''){return `<div class="page-head"><div><span class="eyebrow">134340 · ${isStaff()?'ADMINISTRACIÓN':'TU UNIVERSO'}</span><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function setupError(){const e=S.errors.filter(x=>!['internal_notes','audit_log'].includes(x.table));return e.length?`<div class="notice warning"><b>No se pudo cargar toda la información</b>${e.map(x=>`<p>${esc(x.table==='sheets'?'Historial de Sheets':x.table)}: ${esc(x.message)}</p>`).join('')}${btn('Volver a comprobar','reload','','light sm')}</div>`:''}
function content(){if(S.route==='login')return auth();if(!S.user&&S.route!=='store')return auth();switch(S.route){case 'store':return store();case 'history':return historyPage();case 'dashboard':return dashboard();case 'orders':return ordersPage();case 'payments':return paymentsPage();case 'shipments':return shipmentsPage();case 'boxes':return boxesPage();case 'inventory':return inventoryPage();case 'customers':return customersPage();case 'private-keys':return privateKeysPage();case 'announcements':return announcementsPage();case 'settings':return settingsPage();case 'masterlist':return masterlistView();default:return store()}}
function store(){if(!S.user)return landing();const categories=[...new Set(rows('products').filter(p=>['open','closed'].includes(p.status)).map(p=>p.category).filter(Boolean))];const list=rows('products').filter(p=>['open','closed'].includes(p.status)&&(S.filter==='all'||p.category===S.filter)&&(p.name+' '+(p.sku||'')).toLowerCase().includes(S.search.toLowerCase()));return `${pageHead('Un pequeño universo, muchas cosas bonitas.','Colecciones, preventas y tesoros para acompañarte.') }<section class="hero"><div><span class="eyebrow">BIENVENIDA A 134340</span><h1>Lo que amas<br>tiene un lugar aquí.</h1><p>Encuentra tu próxima colección y acompaña cada pedido, desde el primer apartado hasta su llegada a casa.</p>${btn(S.user?'Ver mis pedidos':'Entrar a mi universo','route',S.user?'orders':'login') }</div><div class="art"><img src="/assets/logo.jpg" alt="Mascota de 134340 con estrellas y constelaciones"><span class="orbit-label">Un universo para coleccionar</span></div></section>${setupError()}<div class="split-title"><h2 style="margin-top:26px">Explora la tienda</h2><small>${list.length} publicaciones</small></div><div class="filters"><input id="search" class="search" placeholder="Buscar productos o códigos" aria-label="Buscar productos" value="${esc(S.search)}"></div><div class="chips">${[['all','Todo'],...categories.map(c=>[c,c])].map(([v,l])=>`<button class="chip ${S.filter===v?'active':''}" data-act="filter" data-id="${esc(v)}">${esc(l)}</button>`).join('')}</div><div class="products">${list.map(productCard).join('')}</div>${!list.length?`<section class="panel">${empty(S.search?'No encontramos ese producto':'Las próximas colecciones están por llegar',S.search?'Prueba con otro nombre o código.':'Cuando la administradora publique productos, aparecerán aquí con sus fotos y opciones.',can('inventory','create')?btn('Publicar mi primer producto','new-product'):'')}</section>`:''}`}
function imagePath(path){const prefix=URL_API+'/storage/v1/object/public/product-images/';return path?.startsWith(prefix)?path.slice(prefix.length):path;}
async function loadImageURLs(){S.imageURLs={};const paths=[...new Set(rows('products').flatMap(p=>p.image_paths||[]).map(imagePath).filter(Boolean))];if(!paths.length)return;try{const signed=await request('/storage/v1/object/sign/product-images',{method:'POST',body:JSON.stringify({paths,expiresIn:3600})});for(const item of signed){if(item.signedURL)S.imageURLs[item.path]=URL_API+'/storage/v1'+item.signedURL;}}catch(e){S.errors.push({table:'fotos',message:errorMessage(e)});}}
function imageURL(path){return S.imageURLs[imagePath(path)]||'/assets/logo.jpg';}
const activeVariants=p=>rows('product_variants').filter(v=>v.product_id===p.id&&v.active);
const isSoldOut=p=>p.sale_type==='stock'&&activeVariants(p).length>0&&activeVariants(p).every(v=>v.stock_quantity<=0);
async function refreshCatalog(){const [ps,vs]=await Promise.all([get('products'),get('product_variants')]);S.data.products=ps;S.data.product_variants=vs;await loadImageURLs();}
function landing(){return `<section class="brand-landing"><span class="eyebrow">TU PEQUEÑO UNIVERSO</span><img src="/assets/logo.jpg" alt="Logo oficial de 134340"><h1>134340</h1><p>Un lugar para lo que amas.</p>${btn('Entrar a mi universo','route','login')}<button class="landing-register" data-act="register">Crear mi cuenta</button><span class="landing-stars" aria-hidden="true">✧ · ✦ · ✧</span></section>`;}

function productCard(p){return `<article class="product"><div class="product-image">${p.image_paths?.[0]?`<img src="${esc(imageURL(p.image_paths[0]))}" alt="${esc(p.name)}" loading="lazy">`:'<img class="placeholder" src="/assets/logo.jpg" alt="Sin fotografía">'}${isSoldOut(p)?'<span class="badge gray">Agotado</span>':badge(p.status==='closed'?'closed':p.sale_type)}</div><div class="product-body"><span class="category">${esc(p.category||'Colecciones 134340')}</span><h3>${esc(p.name)}</h3><div class="meta">${p.closes_at?'Cierre: '+date(p.closes_at):'Consulta los detalles'}</div><div class="product-bottom"><span class="price">${money(p.price,p.currency)}</span>${btn(isSoldOut(p)?'Ver · agotado':'Ver detalles','product',p.id,'soft sm')}</div></div></article>`}
function stat(label,value,note,icon){return `<div class="stat">${ic(icon)}<small>${label}</small><strong>${value}</strong><p>${note}</p></div>`}
function dashboard(){const orders=rows('orders'),charges=rows('charges'),payments=rows('payments'),shipments=rows('shipments');const paid=payments.filter(p=>p.status==='approved').reduce((a,p)=>a+Number(p.amount),0);const currencies=[...new Set(payments.filter(p=>p.status==='approved').map(p=>charges.find(c=>c.id===p.charge_id)?.currency||'MXN'))];const name=S.profile?.full_name?.split(' ')[0]||(isStaff()?'administradora':'coleccionista');return `${pageHead(`Hola, ${esc(name)}.`,isStaff()?'Esto está pasando en tu tienda.':'Tus colecciones, cada vez más cerca de casa.',btn('Mi perfil','my-profile','','light'))}<section class="hero"><div><span class="eyebrow">TODO EN SU ÓRBITA</span><h1>${isStaff()?'Tu tienda, en un<br>solo universo.':'Tu próxima alegría<br>está en camino.'}</h1><p>${isStaff()?'Revisa tus pedidos, acompaña a tus clientas y mantén cada entrega al día.':'Aquí puedes seguir tus pedidos, consultar tus cargos y compartir tus comprobantes.'}</p>${btn(isStaff()?'Revisar pagos':'Ver mis pedidos','route',isStaff()?'payments':'orders')}</div><div class="art"><img src="/assets/logo.jpg" alt=""><span class="orbit-label">El V-endedor está de tu lado</span></div></section>${setupError()}${linkBanner()}<section class="stats">${stat(isStaff()?'Pagos aprobados':'Total pagado',currencies.length>1?'Varias monedas':money(paid,currencies[0]||'MXN'),'Acumulado · sin descontar reembolsos','payments')}${stat('Pedidos activos',orders.filter(o=>!['delivered','cancelled'].includes(o.status)).length,'Pendientes de completar','orders')}${stat('Por verificar',payments.filter(p=>p.status==='pending').length,'Comprobantes pendientes','payments')}${stat(isStaff()?'Clientas registradas':'Cargos pendientes',isStaff()?rows('profiles').filter(p=>!rows('staff_access').some(s=>s.user_id===p.id&&s.active)).length:charges.filter(c=>chargeBalance(c)>0).length,isStaff()?'Perfiles del portal':'Con saldo por cubrir','customers')}</section><div class="grid2"><section class="panel"><div class="panel-head"><div><h2>${isStaff()?'Pedidos recientes':'Mis pedidos recientes'}</h2><p>El siguiente paso de cada colección.</p></div>${btn('Ver todos','route','orders','light sm')}</div>${orderTable([...orders].sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,5))}</section><section class="panel"><div class="panel-head"><h2>Avisos de tu universo</h2>${ic('announcements')}</div>${announcementList(rows('announcements').filter(a=>a.published).slice(0,3))}<div class="notice"><b>${shipments.filter(s=>!['delivered','cancelled'].includes(s.status)).length} envíos en seguimiento</b><p>${charges.filter(c=>chargeBalance(c)>0).length} cargos con saldo pendiente.</p></div></section></div>`}
function orderTable(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>PEDIDO</th>${isStaff()?'<th>CLIENTA</th>':''}<th>FECHA</th><th>ESTADO</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><b>#${String(o.order_number).padStart(4,'0')}</b></td>${isStaff()?`<td>${esc(customer(o.customer_id))}</td>`:''}<td>${date(o.created_at)}</td><td>${badge(o.status)}</td><td>${btn('Detalle','order',o.id,'light sm')}</td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no hay pedidos','Aquí aparecerán los pedidos registrados en el portal.')}
function ordersPage(){let list=rows('orders').filter(o=>(S.filter==='all'||o.status===S.filter)&&(`${o.order_number} ${customer(o.customer_id)} ${rows('order_items').filter(i=>i.order_id===o.id).map(i=>i.product_name).join(' ')}`).toLowerCase().includes(S.search.toLowerCase()));return `${pageHead(isStaff()?'Pedidos':'Mis pedidos','Productos, variantes y seguimiento en un mismo lugar.',can('orders','create')?btn('+ Pedido personalizado','new-order'):'')}${setupError()}<div class="filters"><input id="search" class="search" aria-label="Buscar pedidos" placeholder="Buscar pedido, producto o clienta" value="${esc(S.search)}"><select id="filter-select" aria-label="Filtrar por estado">${[['all','Todos los estados'],...['pending','confirmed','purchasing','production','in_transit','in_warehouse','shipped','delivered','cancelled'].map(x=>[x,labels[x]])].map(([v,l])=>`<option value="${v}" ${S.filter===v?'selected':''}>${l}</option>`).join('')}</select></div><section class="panel">${orderTable(list)}</section>${historyTeaser()}`} 
function paymentsPage(){const cs=rows('charges').filter(c=>`${customer(c.customer_id)} ${c.description}`.toLowerCase().includes(S.search.toLowerCase()));const ps=rows('payments').filter(p=>S.filter==='all'||p.status===S.filter);return `${pageHead(isStaff()?'Pagos y cargos':'Mis pagos','Cada concepto, su importe y su comprobante.',can('payments','create')?`<div class="actions">${btn('Cobrar EMS / aduana','route','boxes','soft')}${btn('+ Otro cargo','new-charge','','light')}</div>`:'')}${setupError()}<div class="filters"><input id="search" class="search" aria-label="Buscar cargos" placeholder="Buscar clienta o concepto" value="${esc(S.search)}"></div><section class="panel"><div class="panel-head"><h2>Cargos y saldos</h2></div>${cs.length?`<div class="table-wrap"><table><thead><tr>${isStaff()?'<th>CLIENTA</th>':''}<th>CONCEPTO</th><th>IMPORTE</th><th>PAGADO</th><th>PENDIENTE</th><th>VENCE</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr>${isStaff()?`<td>${esc(customer(c.customer_id))}</td>`:''}<td><b>${esc(c.description)}</b><br><small>${esc(labels[c.concept]||c.concept)}</small></td><td>${money(c.amount,c.currency)}</td><td>${money(chargePaid(c),c.currency)}</td><td>${money(chargeBalance(c),c.currency)}</td><td>${date(c.due_at)}</td><td>${!isStaff()&&chargeBalance(c)>0?btn('Subir comprobante','proof',c.id,'soft sm'):chargeBalance(c)===0?badge('approved'):''}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin cargos registrados','Los cargos de producto, EMS, aduana y envío aparecerán por separado.')}</section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Comprobantes</h2><select id="filter-select" aria-label="Estado de comprobantes"><option value="all">Todos</option>${['pending','approved','rejected'].map(x=>`<option value="${x}" ${S.filter===x?'selected':''}>${labels[x]}</option>`).join('')}</select></div>${ps.length?`<div class="table-wrap"><table><thead><tr><th>FECHA</th>${isStaff()?'<th>CLIENTA</th>':''}<th>IMPORTE</th><th>ESTADO</th><th>REVISIÓN</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td>${date(p.created_at)}</td>${isStaff()?`<td>${esc(customer(p.customer_id))}</td>`:''}<td>${money(p.amount,rows('charges').find(c=>c.id===p.charge_id)?.currency)}</td><td>${badge(p.status)}</td><td>${esc(p.rejection_reason||'—')}</td><td><div class="row-actions">${p.receipt_path?btn('Ver archivo','receipt',p.id,'light sm'):''}${p.status==='pending'&&can('payments','approve')?btn('Revisar','review',p.id,'soft sm'):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Sin comprobantes','Los archivos enviados por las clientas aparecerán aquí para su revisión.')}</section>`}
function shipmentsPage(){return `${pageHead(isStaff()?'Envíos':'Mis envíos','Consolidaciones, guías y entregas personales.',can('shipments','create')?btn('+ Preparar envío','new-shipment'):'')}${setupError()}<section class="panel">${rows('shipments').length?`<div class="table-wrap"><table><thead><tr>${isStaff()?'<th>CLIENTA</th>':''}<th>PAQUETE</th><th>TRANSPORTE</th><th>GUÍA</th><th>ESTADO</th><th></th></tr></thead><tbody>${rows('shipments').map(s=>`<tr>${isStaff()?`<td>${esc(customer(s.customer_id))}</td>`:''}<td>${esc(s.package_code)}</td><td>${esc(s.carrier||'Entrega personal')}</td><td>${esc(s.tracking_number||'Por asignar')}</td><td>${badge(s.status)}</td><td>${btn('Detalle','shipment',s.id,'light sm')}</td></tr>`).join('')}</tbody></table></div>`:empty('Cada paquete tendrá su órbita','Aquí aparecerán los pedidos por consolidar, sus guías y las entregas personales.')}</section>`}
function inventoryPage(){if(!can('inventory'))return empty('Acceso restringido','Tu cuenta no tiene acceso al inventario.');const list=rows('products').filter(p=>`${p.name} ${p.sku||''}`.toLowerCase().includes(S.search.toLowerCase()));return `${pageHead('Productos e inventario','Publica colecciones y administra opciones y existencias.',can('inventory','create')?btn('+ Nuevo producto','new-product'):'')}${setupError()}<div class="filters"><input id="search" class="search" aria-label="Buscar inventario" placeholder="Buscar producto o SKU" value="${esc(S.search)}"></div><section class="panel">${list.length?`<div class="table-wrap"><table><thead><tr><th>PRODUCTO</th><th>PRECIO</th><th>TIPO</th><th>ESTADO</th><th>EXISTENCIAS</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><b>${esc(p.name)}</b><br><small>${esc(p.sku||'Sin SKU')}</small></td><td>${money(p.price,p.currency)}</td><td>${badge(p.sale_type)}</td><td>${badge(p.status)}</td><td>${p.sale_type==='stock'?rows('product_variants').filter(v=>v.product_id===p.id).reduce((a,v)=>a+v.stock_quantity,0):'Por encargo'}</td><td><div class="row-actions">${can('inventory','edit')?btn('Editar','edit-product',p.id,'light sm')+btn('Opciones','variants',p.id,'soft sm'):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Tu primera colección empieza aquí','Agrega fotos, precio, variantes y fecha de cierre.',can('inventory','create')?btn('Crear producto','new-product'):'')}</section>`}
function customersPage(){if(!can('customers'))return empty('Acceso restringido','Tu cuenta no tiene acceso a las clientas.');const ps=rows('profiles').filter(p=>`${p.full_name||''} ${p.customer_code||''}`.toLowerCase().includes(S.search.toLowerCase()));return `${pageHead('Clientas','Su historial, sus pedidos y los detalles que importan.')}${setupError()}<div class="filters"><input id="search" class="search" aria-label="Buscar clientas" placeholder="Buscar nombre o código" value="${esc(S.search)}"></div><section class="panel">${ps.length?`<div class="table-wrap"><table><thead><tr><th>CLIENTA</th><th>CÓDIGO</th><th>PEDIDOS</th><th>REGISTRO</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><b>${esc(p.full_name||'Sin nombre')}</b></td><td>${esc(p.customer_code||'Por asignar')}</td><td>${rows('orders').filter(o=>o.customer_id===p.id).length}</td><td>${date(p.created_at)}</td><td>${btn('Ver perfil','customer',p.id,'light sm')}</td></tr>`).join('')}</tbody></table></div>`:empty('Las clientas aparecerán aquí','Cada registro del portal tendrá un perfil propio.')}</section>${legacyCustomersPanel()}`} 
function announcementList(list){return list.length?list.map(a=>`<article class="notice"><small>${date(a.created_at)} · ${a.target_customer_id?'Aviso personal':'Para todas'}</small><h3 style="margin:7px 0">${esc(a.title)}</h3><p>${esc(a.body)}</p>${can('announcements','edit')?btn(a.published?'Ocultar':'Publicar','toggle-announcement',a.id,'light sm'):''}</article>`).join(''):empty('Un universo tranquilo','Los avisos nuevos aparecerán aquí.')}
function announcementsPage(){return `${pageHead('Tablón de avisos','Novedades, llegadas y fechas importantes.',can('announcements','create')?btn('+ Nuevo aviso','new-announcement'):'')}${setupError()}<section class="panel">${announcementList([...rows('announcements')].sort((a,b)=>b.created_at.localeCompare(a.created_at)))}</section>`}
function settingsPage(){if(!isAdmin())return empty('Acceso restringido','Solo la administradora puede gestionar permisos.');return `${pageHead('Equipo y permisos','Cada persona, con el acceso que necesita.',btn('+ Configurar acceso','staff-form'))}${setupError()}<section class="panel"><div class="notice"><b>Las cuentas del portal son independientes de Supabase y Netlify.</b><p>Para agregar personal, primero debe registrarse en el portal. Después asígnale acceso usando su perfil.</p></div><div class="table-wrap"><table><thead><tr><th>PERSONA</th><th>ROL</th><th>ESTADO</th><th></th></tr></thead><tbody>${rows('staff_access').map(s=>`<tr><td>${esc(customer(s.user_id))}</td><td>${badge(s.role)}</td><td>${s.active?'Activo':'Suspendido'}</td><td>${btn('Permisos','staff-form',s.user_id,'light sm')}</td></tr>`).join('')}</tbody></table></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Historial de cambios</h2></div>${rows('audit_log').length?`<div class="table-wrap"><table><thead><tr><th>FECHA</th><th>PERSONA</th><th>SECCIÓN</th><th>ACCIÓN</th></tr></thead><tbody>${[...rows('audit_log')].sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,50).map(a=>`<tr><td>${date(a.created_at)}</td><td>${esc(a.actor_id?customer(a.actor_id):'Configuración inicial')}</td><td>${esc(a.table_name)}</td><td>${esc(a.operation)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Los movimientos quedarán registrados al instalar la configuración 03.</p>'}</section>`}
function auth(){const mode=S.authMode,signup=mode==='signup',reset=mode==='reset';return `<section class="panel auth-wrap"><span class="eyebrow">BIENVENIDA A 134340</span><h1>${signup?'Tu universo empieza aquí.':reset?'Recupera tu acceso.':'Qué bonito verte aquí.'}</h1><p>${signup?'Crea tu cuenta con tu nombre, correo y una contraseña.':reset?'Escribe tu correo y te enviaremos un enlace para crear una nueva contraseña.':'Entra con tu correo y contraseña para consultar tus pedidos, pagos y envíos.'}</p><form data-form="auth">${signup?field('name','Tu nombre','text','','required maxlength="100" autocomplete="name"'):''}${field('email','Correo electrónico','email',S.authEmail||'','required autocomplete="email"')}${reset?'':field('password','Contraseña','password','','required minlength="8" autocomplete="'+(signup?'new-password':'current-password')+'"')}${signup?field('confirm','Confirma tu contraseña','password','','required minlength="8" autocomplete="new-password"'):''}<button class="btn" type="submit">${signup?'Crear mi cuenta':reset?'Enviar enlace de recuperación':'Entrar a mi universo'}</button><p id="form-error" class="form-hint" role="alert"></p></form>${mode==='login'?'<p class="form-hint">¿Antes entrabas con un código por correo? Usa “Olvidé mi contraseña” para crear tu contraseña.</p>':''}<div class="chips">${signup||reset?btn('Ya tengo cuenta','auth-mode','login','light sm'):btn('Crear cuenta','auth-mode','signup','light sm')}${reset?'':btn('Olvidé mi contraseña','auth-mode','reset','light sm')}</div></section>`}
async function openProduct(id){
 if(!demo)await refreshCatalog();
 const p=rows('products').find(p=>p.id===id);if(!p)throw new Error('Este producto ya no está disponible.');
 const vs=activeVariants(p);const available=vs.filter(v=>p.sale_type!=='stock'||v.stock_quantity>0);
 showModal(p.name,`${p.image_paths?.[0]?`<img class="detail-img" src="${esc(imageURL(p.image_paths[0]))}" alt="${esc(p.name)}">`:''}${badge(p.sale_type)}<p style="white-space:pre-wrap;margin-top:12px">${esc(p.description||'Una nueva pieza para tu colección.')}</p><div class="summary-line"><span>Precio del producto</span><b>${money(p.price,p.currency)}</b></div>${p.deposit_amount?`<div class="summary-line"><span>Apartado indicado</span><b>${money(p.deposit_amount,p.currency)}</b></div>`:''}<p class="form-hint">EMS, aduana y envío se mostrarán como cargos separados cuando correspondan. ${p.closes_at?'Cierre: '+date(p.closes_at):''}</p>${p.status==='open'&&(!p.closes_at||new Date(p.closes_at)>new Date())?S.user?isSoldOut(p)?'<div class="notice"><b>Agotado</b><p>Las piezas disponibles ya fueron apartadas. Puedes seguir explorando la tienda.</p></div>':available.length?form('purchase',`<input type="hidden" name="product_id" value="${p.id}">${select('variant_id','Elige tu opción',available.map(v=>[v.id,v.name+(p.sale_type==='stock'?' · '+v.stock_quantity+' disponibles':'')]))}${field('quantity','Cantidad','number',1,'required min="1" max="'+(p.sale_type==='stock'?Math.min(100,available[0].stock_quantity):100)+'"')}${textarea('note','Nota para tu pedido')}`,'Confirmar pedido'):'<div class="notice">La administradora está preparando las opciones de este producto.</div>':btn('Inicia sesión para pedir','login-close'):'<div class="notice">Esta colección ya cerró.</div>'}`);
}

function productForm(p={}){showModal(p.id?'Editar producto':'Nueva colección',form('product',`<input type="hidden" name="id" value="${esc(p.id||'')}"><div class="form-grid">${field('name','Nombre del producto','text',p.name,'required maxlength="200"')}${field('sku','SKU / código','text',p.sku)}${field('category','Categoría','text',p.category)}${select('sale_type','Tipo',[['preorder','Preventa'],['stock','Stock'],['custom','Personalizado']],p.sale_type||'preorder')}${field('price','Precio del producto','number',p.price??'','required min="0" step="0.01"')}${select('currency','Moneda',[['MXN','MXN'],['USD','USD'],['KRW','KRW']],p.currency||'MXN')}${field('deposit_amount','Apartado (opcional)','number',p.deposit_amount,'min="0" step="0.01"')}${select('status','Publicación',['draft','open','closed','archived'].map(x=>[x,labels[x]]),p.status||'draft')}${field('closes_at','Fecha de cierre','datetime-local',localDate(p.closes_at))}${field('payment_due_at','Fecha de liquidación','datetime-local',localDate(p.payment_due_at))}${textarea('description','Descripción',p.description)}<div class="field full"><label for="f-photos">Fotos (JPG, PNG o WebP · máximo 5 MB cada una)</label><input id="f-photos" name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple><small>Las nuevas fotos se agregan a las actuales. Crea al menos una opción antes de abrir pedidos.</small></div></div>`))}
function localDate(x){if(!x)return '';const d=new Date(x);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function showOrder(id){const o=rows('orders').find(o=>o.id===id),items=rows('order_items').filter(i=>i.order_id===id);showModal('Pedido #'+String(o.order_number).padStart(4,'0'),`${badge(o.status)}<p>${esc(customer(o.customer_id))} · ${date(o.created_at)}</p>${items.map(i=>`<div class="summary-line"><span>${esc(i.product_name)}<br><small>${esc(i.variant_name||'')} × ${i.quantity}</small></span><b>${money(i.quantity*i.unit_price,o.currency)}</b></div>`).join('')}<div class="summary-line total"><span>Total de productos</span><span>${money(items.reduce((a,i)=>a+i.quantity*i.unit_price,0),o.currency)}</span></div><p>${esc(o.customer_note||'')}</p>${can('orders','edit')?form('order-status',`<input type="hidden" name="id" value="${o.id}">${select('status','Estado',['pending','confirmed','purchasing','production','in_transit','in_warehouse','shipped','delivered','cancelled'].map(x=>[x,labels[x]]),o.status)}`,'Actualizar estado'):''}<p class="form-hint">Cambiar el estado a cancelado no reembolsa pagos ni repone existencias automáticamente.</p>`)}
function variantsForm(id){const vs=rows('product_variants').filter(v=>v.product_id===id);showModal('Opciones y existencias',`${vs.map(v=>`<div class="summary-line"><span>${esc(v.name)} · ${v.stock_quantity} disponibles</span>${btn('Editar','edit-variant',v.id,'light sm')}</div>`).join('')}<h3 style="margin-top:20px">Agregar opción</h3>${variantFields({product_id:id})}`)}
function variantFields(v){return form('variant',`<input type="hidden" name="id" value="${v.id||''}"><input type="hidden" name="product_id" value="${v.product_id}">${field('name','Opción (ej. Jin · talla M)','text',v.name,'required')}${field('sku','SKU de la opción','text',v.sku)}${field('stock_quantity','Existencias disponibles','number',v.stock_quantity??0,'required min="0" step="1"')}${select('active','Disponible',[['true','Sí'],['false','No']],String(v.active??true))}`)}
function newOrderForm(){showModal('Pedido personalizado',form('custom-order',`${select('customer_id','Clienta',rows('profiles').map(p=>[p.id,customer(p.id)]),'','required')}${field('name','Producto o encargo','text','','required')}${field('variant','Versión / talla / integrante') }<div class="form-grid">${field('quantity','Cantidad','number',1,'required min="1" max="100"')}${field('price','Precio unitario','number','','required min="0" step="0.01"')}${select('currency','Moneda',[['MXN','MXN'],['USD','USD'],['KRW','KRW']])}${field('due_at','Fecha de pago','datetime-local')}</div>${textarea('note','Nota visible para la clienta')}`,'Crear pedido y cargo'))}
function newChargeForm(){showModal('Otro cargo',form('charge',`${select('customer_id','Clienta',rows('profiles').map(p=>[p.id,customer(p.id)]),'','required')}${select('concept','Concepto',['product','shipping','other'].map(x=>[x,labels[x]]))}${field('description','Descripción','text','','required') }<div class="form-grid">${field('amount','Importe','number','','required min="0.01" step="0.01"')}${select('currency','Moneda',[['MXN','MXN'],['USD','USD'],['KRW','KRW']])}</div>${field('due_at','Fecha límite','datetime-local')}`))}
function proofForm(id){const c=rows('charges').find(c=>c.id===id);showModal('Subir comprobante',`<p>${esc(c.description)} · Pendiente: <b>${money(chargeBalance(c),c.currency)}</b></p>${form('proof',`<input type="hidden" name="charge_id" value="${id}">${field('amount','Importe de este pago','number','','required min="0.01" step="0.01" max="'+chargeBalance(c)+'"')}${field('method','Método / banco','text','','required')}${field('reference','Referencia (opcional)')}<div class="field"><label for="f-receipt">Comprobante (imagen o PDF, hasta 5 MB)</label><input id="f-receipt" name="receipt" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" required></div>`,'Enviar para revisión')}`)}
function reviewForm(id){const p=rows('payments').find(p=>p.id===id);showModal('Revisar comprobante',`<p>${esc(customer(p.customer_id))} · ${money(p.amount,rows('charges').find(c=>c.id===p.charge_id)?.currency)}</p>${p.receipt_path?btn('Abrir comprobante','receipt',p.id,'light'):''}${form('review',`<input type="hidden" name="id" value="${id}">${select('decision','Decisión',[['approved','Aprobar'],['rejected','Rechazar']])}${textarea('reason','Motivo (obligatorio al rechazar)')}`,'Confirmar revisión')}`)}
function shipmentForm(s={}){const items=rows('order_items').filter(i=>rows('orders').some(o=>o.id===i.order_id&&(!s.customer_id||o.customer_id===s.customer_id)));showModal(s.id?'Editar envío':'Preparar envío',form('shipment',`<input type="hidden" name="id" value="${s.id||''}">${select('customer_id','Clienta',rows('profiles').map(p=>[p.id,customer(p.id)]),s.customer_id,'required')}${field('package_code','Código de paquete','text',s.package_code,'required')}${select('delivery_type','Tipo',[['shipping','Envío'],['personal','Entrega personal']],s.delivery_type||'shipping')}${field('carrier','Paquetería','text',s.carrier)}${field('tracking_number','Número de guía','text',s.tracking_number)}${select('status','Estado',['consolidating','ready','shipped','delivered','cancelled'].map(x=>[x,labels[x]]),s.status||'consolidating')}${textarea('notes','Instrucciones visibles',s.notes)}${s.id?'':`<div class="field"><label for="f-item_ids">Productos por consolidar</label><select name="item_ids" id="f-item_ids" multiple size="5">${items.map(i=>`<option value="${i.id}">${esc(customer(rows('orders').find(o=>o.id===i.order_id)?.customer_id))} · ${esc(i.product_name)} × ${i.quantity}</option>`).join('')}</select><small>Selecciona productos de la misma clienta. La operación valida la pertenencia y evita duplicarlos en otro envío activo.</small></div>`}`))}
function showShipment(id){const s=rows('shipments').find(x=>x.id===id);const its=rows('shipment_items').filter(x=>x.shipment_id===id);showModal(s.package_code,`${badge(s.status)}<p>${esc(s.carrier||'Entrega personal')}<br>Guía: <b>${esc(s.tracking_number||'Por asignar')}</b></p>${its.map(x=>{const i=rows('order_items').find(i=>i.id===x.order_item_id);return `<div class="summary-line"><span>${esc(i?.product_name||'Producto')}</span><b>× ${i?.quantity||''}</b></div>`}).join('')}<p style="white-space:pre-wrap">${esc(s.notes||'')}</p>${can('shipments','edit')?btn('Editar envío','edit-shipment',id,'soft'):''}`)}
function customerForm(id){const p=rows('profiles').find(x=>x.id===id),d=rows('customer_details').find(x=>x.customer_id===id)||{};showModal(p.full_name||'Perfil de clienta',`${form('customer',`<input type="hidden" name="id" value="${id}">${field('full_name','Nombre','text',p.full_name)}${field('customer_code','Código de clienta','text',p.customer_code)}${field('phone','Teléfono','tel',d.phone)}${field('instagram','Instagram','text',d.instagram)}${textarea('address','Dirección de envío',d.address)}`,can('customers','edit')?'Guardar perfil':'Consultar')}<h3 style="margin-top:22px">Historial de pedidos</h3>${orderTable(rows('orders').filter(o=>o.customer_id===id))}<h3 style="margin-top:22px">Notas internas</h3>${rows('internal_notes').filter(n=>n.customer_id===id).map(n=>`<div class="notice"><small>${date(n.created_at)}</small><p>${esc(n.body)}</p></div>`).join('')}${can('customers','edit')?form('note',`<input type="hidden" name="customer_id" value="${id}">${textarea('body','Nueva nota (solo personal autorizado)')}`,'Guardar nota'):''}`);if(!can('customers','edit'))modal.querySelector('form button[type=submit], form [data-act=submit]')?.remove()}
function staffForm(id){const st=rows('staff_access').find(x=>x.user_id===id)||{};const perm=rows('staff_permissions').filter(x=>x.user_id===id);showModal('Configurar acceso',form('staff',`${select('user_id','Cuenta del portal',rows('profiles').map(p=>[p.id,customer(p.id)]),id,'required')}${select('role','Rol',[['staff','Personal'],['admin','Administradora · acceso completo']],st.role||'staff')}${select('active','Acceso',[['true','Activo'],['false','Suspendido']],String(st.active??true))}<p class="form-hint">Para el rol de personal, selecciona acciones por sección. Activa “Ver” para poder usar la sección.</p><div class="table-wrap"><table><thead><tr><th>SECCIÓN</th>${['view','create','edit','approve','delete'].map(x=>`<th>${({view:'Ver',create:'Crear',edit:'Editar',approve:'Aprobar',delete:'Eliminar'})[x]}</th>`).join('')}</tr></thead><tbody>${[['customers','Clientas'],['orders','Pedidos'],['payments','Pagos'],['shipments','Envíos'],['inventory','Inventario'],['announcements','Avisos']].map(([m,l])=>`<tr><td>${l}</td>${['view','create','edit','approve','delete'].map(a=>`<td><input type="checkbox" name="permission" value="${m}:${a}" aria-label="${l} ${a}" ${perm.some(p=>p.module===m&&p.action===a)?'checked':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div>`))}
async function upload(bucket,file){if(!file||!file.size)throw new Error('Selecciona un archivo.');if(file.size>5*1024*1024)throw new Error('Cada archivo debe pesar como máximo 5 MB.');const mime={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','application/pdf':'pdf'};if(!mime[file.type]||(bucket==='product-images'&&file.type==='application/pdf'))throw new Error('Formato de archivo no permitido.');const path=S.user.id+'/'+crypto.randomUUID()+'.'+mime[file.type];await request('/storage/v1/object/'+bucket+'/'+path,{method:'POST',headers:{'Content-Type':file.type,'x-upsert':'false'},body:file});return path}
async function receipt(id){const p=rows('payments').find(x=>x.id===id);if(!p?.receipt_path)throw new Error('Este comprobante no tiene archivo.');const w=window.open('about:blank','_blank');if(w)w.opener=null;try{const data=await request('/storage/v1/object/sign/receipts/'+p.receipt_path,{method:'POST',body:JSON.stringify({expiresIn:120})});const u=URL_API+'/storage/v1'+data.signedURL;if(w)w.location=u;else toast('Permite abrir ventanas para ver el comprobante.')}catch(e){w?.close();throw e}}
async function handleForm(f){if(f.dataset.submitting==='true')return;const fd=new FormData(f),v=Object.fromEntries(fd),kind=f.dataset.form;const button=f.querySelector('button[type=submit], [data-act=submit]');const err=f.querySelector('#form-error');if(err)err.textContent='';if(demo){toast('Esta es una vista de diseño; no guarda cambios.');return}if(button)button.disabled=true;f.dataset.submitting='true';try{
 if(kind==='box-create'||kind==='box-status'||kind==='box-charge'){await handleBoxForm(f,v,fd);modal.close();toast('Guardado correctamente.');await loadBoxes();return;}
 if(kind==='auth'){
  const email=v.email.trim().toLowerCase();S.authEmail=email;saveSession(null);
  if(S.authMode==='reset'){await request('/auth/v1/recover?redirect_to='+encodeURIComponent(location.origin+'/'),{method:'POST',body:JSON.stringify({email})});toast('Si la cuenta existe, recibirás un correo con un enlace para crear una nueva contraseña.');S.authMode='login';render();return}
  if(S.authMode==='signup'){if(v.password!==v.confirm)throw new Error('Las contraseñas no coinciden.');const name=v.name.trim();const d=await request('/auth/v1/signup?redirect_to='+encodeURIComponent(location.origin+'/'),{method:'POST',body:JSON.stringify({email,password:v.password,data:{full_name:name}})});if(!d.access_token){S.authMode='login';render();toast('Revisa tu correo para confirmar tu cuenta y después inicia sesión.');return}saveSession(d);await rpc('update_my_profile',{p_name:name,p_phone:null,p_instagram:null,p_address:null});}
  else saveSession(await request('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email,password:v.password})}));
  S.authMode='login';S.route='dashboard';await load();return;
 }
 if(kind==='recovery'){if(v.password!==v.confirm)throw new Error('Las contraseñas no coinciden.');await request('/auth/v1/user',{method:'PUT',body:JSON.stringify({password:v.password})});toast('Contraseña actualizada. Ya puedes entrar con tu correo y contraseña.');modal.close();S.route='dashboard';await load();return}
 if(kind==='claim'){const result=await rpc('claim_legacy_history',{p_key:v.key});if(!result.ok)throw new Error(result.message);f.reset();modal.close();toast(result.message);S.route='history';await load();return;}
 if(kind==='product'){const old=rows('products').find(p=>p.id===v.id);const paths=[...(old?.image_paths||[])];const files=fd.getAll('photos').filter(x=>x.size);if(paths.length+files.length>8)throw new Error('Puedes agregar hasta 8 fotos por producto.');for(const file of files)paths.push(await upload('product-images',file));const d={name:v.name.trim(),sku:v.sku.trim()||null,category:v.category.trim()||null,sale_type:v.sale_type,status:v.status,price:Number(v.price),currency:v.currency,deposit_amount:v.deposit_amount?Number(v.deposit_amount):null,closes_at:v.closes_at?new Date(v.closes_at).toISOString():null,payment_due_at:v.payment_due_at?new Date(v.payment_due_at).toISOString():null,description:v.description,image_paths:paths};if(d.deposit_amount>d.price)throw new Error('El apartado no puede superar el precio.');const out=v.id?await update('products',v.id,d):await insert('products',d);modal.close();await load();variantsForm(out[0].id);toast('Producto guardado. Revisa sus opciones.');return}
 if(kind==='variant'){const d={product_id:v.product_id,name:v.name.trim(),sku:v.sku.trim()||null,stock_quantity:Number(v.stock_quantity),active:v.active==='true'};if(!Number.isInteger(d.stock_quantity))throw new Error('Las existencias deben ser un número entero.');v.id?await update('product_variants',v.id,d):await insert('product_variants',d)}
 if(kind==='purchase'){const token=f.dataset.requestId||(f.dataset.requestId=crypto.randomUUID());await rpc('place_order',{p_variant_id:v.variant_id,p_quantity:Number(v.quantity),p_note:v.note,p_request_id:token});S.route='orders';toast('Tu pedido quedó registrado. Consulta sus cargos en Mis pagos.')}
 if(kind==='custom-order')await rpc('create_custom_order',{p_customer_id:v.customer_id,p_name:v.name,p_variant:v.variant,p_quantity:Number(v.quantity),p_price:Number(v.price),p_currency:v.currency,p_due_at:v.due_at?new Date(v.due_at).toISOString():null,p_note:v.note,p_request_id:f.dataset.requestId||(f.dataset.requestId=crypto.randomUUID())});
 if(kind==='order-status')await update('orders',v.id,{status:v.status});
 if(kind==='charge')await insert('charges',{customer_id:v.customer_id,concept:v.concept,description:v.description,amount:Number(v.amount),currency:v.currency,due_at:v.due_at?new Date(v.due_at).toISOString():null});
 if(kind==='proof'){const path=f.dataset.uploadPath||await upload('receipts',fd.get('receipt'));f.dataset.uploadPath=path;await rpc('submit_payment',{p_charge_id:v.charge_id,p_amount:Number(v.amount),p_method:v.method,p_reference:v.reference,p_receipt_path:path});}
 if(kind==='review'){if(v.decision==='rejected'&&!v.reason.trim())throw new Error('Escribe el motivo del rechazo.');await rpc('review_payment',{p_payment_id:v.id,p_decision:v.decision,p_reason:v.reason});}
 if(kind==='shipment'){const d={customer_id:v.customer_id,package_code:v.package_code,delivery_type:v.delivery_type,carrier:v.carrier||null,tracking_number:v.tracking_number||null,status:v.status,notes:v.notes};if(v.id)await rpc('edit_shipment',{p_id:v.id,p_changes:d});else await rpc('create_shipment',{p_data:d,p_item_ids:fd.getAll('item_ids')});}
 if(kind==='my-profile')await rpc('update_my_profile',{p_name:v.name,p_phone:v.phone,p_instagram:v.instagram,p_address:v.address});
 if(kind==='customer')await rpc('update_customer',{p_id:v.id,p_name:v.full_name,p_code:v.customer_code||null,p_phone:v.phone,p_instagram:v.instagram,p_address:v.address});
 if(kind==='note'){if(!v.body.trim())throw new Error('Escribe la nota.');await insert('internal_notes',{customer_id:v.customer_id,body:v.body})}
 if(kind==='announcement')await insert('announcements',{title:v.title,body:v.body,published:v.published==='true',target_customer_id:v.target_customer_id||null});
 if(kind==='staff')await rpc('set_staff_access',{p_user_id:v.user_id,p_role:v.role,p_active:v.active==='true',p_permissions:fd.getAll('permission').map(x=>{const [module,action]=x.split(':');return {module,action}})});
 modal.close();toast('Guardado correctamente.');await load();
 }catch(e){if(kind==='purchase'&&!demo){try{await refreshCatalog();const p=rows('products').find(p=>p.id===v.product_id);const chosen=rows('product_variants').find(x=>x.id===v.variant_id);if(p&&isSoldOut(p)){await openProduct(p.id);toast('Se agotó antes de confirmar tu pedido. No se creó un pedido adicional.');return;}const quantity=f.querySelector('[name=quantity]');if(quantity&&p?.sale_type==='stock'){quantity.max=String(chosen?.stock_quantity||0);if(chosen?.stock_quantity===0){await openProduct(p.id);toast('Esta opción se agotó. Revisa las opciones disponibles.');return;}}}catch{} }if(err)err.textContent=errorMessage(e);else toast(errorMessage(e))}finally{f.dataset.submitting='false';if(button)button.disabled=false}}
document.addEventListener('submit',e=>{if(e.target.matches('form[data-form]')){e.preventDefault();handleForm(e.target)}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b)return;const {act,id}=b.dataset;try{switch(act){case 'submit':return;case 'close':modal.close();break;case 'route':S.route=id;S.search='';S.filter=id==='history'?'order':'all';S.historyLimit=50;render();window.scrollTo(0,0);if(id==='history'&&!S.sheetsLoaded&&!demo){S.busy=true;render();await loadSheetsHistory();S.busy=false;render()}if(id==='boxes')await loadBoxes();if(id==='masterlist')await openMasterlist();if(id==='private-keys')await loadPrivateKeys();break;case 'history-more':S.historyLimit=(S.historyLimit||50)+50;render();break;case 'private-keys-refresh':await loadPrivateKeys();break;case 'copy-private-key':{const item=rows('private_keys').find(x=>x.code===id);if(!item?.key)throw new Error('La clave no está disponible.');await copyText(item.key);toast('Clave copiada. Envíala por mensaje privado.');break;}case 'filter':S.filter=id;render();break;case 'claim':claimForm();break;case 'legacy-customer':await showLegacyCustomer(id);break;case 'import-review':await importReview();break;case 'register':S.authMode='signup';S.route='login';render();break;case 'auth-mode':S.authMode=id;render();break;case 'reload':await load();break;case 'logout':window.Masterlist?.invalidate();if(!demo&&S.session)await request('/auth/v1/logout',{method:'POST'}).catch(()=>{});saveSession(null);location.href='/';break;case 'product':await openProduct(id);break;case 'login-close':modal.close();S.route='login';render();break;case 'my-profile':showModal('Mi perfil',form('my-profile',`${field('name','Nombre','text',S.profile?.full_name,'required')}${field('phone','Teléfono','tel',rows('customer_details').find(x=>x.customer_id===S.user.id)?.phone)}${field('instagram','Instagram','text',rows('customer_details').find(x=>x.customer_id===S.user.id)?.instagram)}${textarea('address','Dirección de envío',rows('customer_details').find(x=>x.customer_id===S.user.id)?.address)}`)+(!isStaff()&&!linkedLegacy()?btn('Vincular historial','claim','','soft'):''));break;case 'new-product':productForm();break;case 'edit-product':productForm(rows('products').find(p=>p.id===id));break;case 'variants':variantsForm(id);break;case 'edit-variant':showModal('Editar opción',variantFields(rows('product_variants').find(v=>v.id===id)));break;case 'order':showOrder(id);break;case 'new-order':newOrderForm();break;case 'box-refresh':await loadBoxes();break;case 'box-new':await newBoxForm();break;case 'box-detail':showBox(id);break;case 'box-charge':boxChargeForm(id);break;case 'new-charge':newChargeForm();break;case 'proof':proofForm(id);break;case 'review':reviewForm(id);break;case 'receipt':if(demo)toast('Los datos de ejemplo no incluyen archivos.');else await receipt(id);break;case 'new-shipment':shipmentForm();break;case 'edit-shipment':shipmentForm(rows('shipments').find(x=>x.id===id));break;case 'shipment':showShipment(id);break;case 'customer':customerForm(id);break;case 'staff-form':staffForm(id);break;case 'new-announcement':showModal('Nuevo aviso',form('announcement',`${field('title','Título','text','','required maxlength="200"')}${textarea('body','Mensaje')}${select('target_customer_id','Destinatarias',[['','Todas las clientas'],...rows('profiles').map(p=>[p.id,customer(p.id)])])}${select('published','Publicación',[['true','Publicar ahora'],['false','Guardar borrador']])}`));break;case 'toggle-announcement':if(demo){toast('La vista de diseño no guarda cambios.');break}const a=rows('announcements').find(x=>x.id===id);await update('announcements',id,{published:!a.published});await load();break;}}catch(err){toast(errorMessage(err))}});
document.addEventListener('input',e=>{if(e.target.id==='private-key-search'){S.privateKeysSearch=e.target.value;const pos=e.target.selectionStart;render();const n=document.querySelector('#private-key-search');n?.focus();n?.setSelectionRange(pos,pos);return}if(e.target.id==='search'){const start=e.target.selectionStart;S.search=e.target.value;render();const n=document.querySelector('#search');n?.focus();n?.setSelectionRange(start,start)}});
document.addEventListener('change',e=>{if(e.target.name==='variant_id'){const f=e.target.closest('form');const p=rows('products').find(x=>x.id===f?.querySelector('[name=product_id]')?.value);const v=rows('product_variants').find(x=>x.id===e.target.value);const q=f?.querySelector('[name=quantity]');if(q&&p?.sale_type==='stock'){q.max=String(Math.min(100,v?.stock_quantity||0));if(Number(q.value)>Number(q.max))q.value=q.max;}}if(e.target.id==='filter-select'){S.filter=e.target.value;render()}});
async function start(){const h=new URLSearchParams(location.hash.slice(1));if(h.has('error')||h.has('error_code')){const expired=h.get('error_code')==='otp_expired';history.replaceState(null,'',location.pathname+location.search);S.route='login';S.authMode=expired?'reset':'login';await load();toast(expired?'El enlace venció o ya fue usado. Solicita uno nuevo.':(h.get('error_description')||'No pudimos validar el enlace.').replace(/\+/g,' '));return}if(h.has('access_token')){saveSession({access_token:h.get('access_token'),refresh_token:h.get('refresh_token'),expires_at:Math.floor(Date.now()/1000)+Number(h.get('expires_in')||3600)});history.replaceState(null,'',location.pathname+location.search);if(h.get('type')==='recovery'){await load();showModal('Nueva contraseña',form('recovery',`${field('password','Nueva contraseña','password','','required minlength="8" autocomplete="new-password"')}${field('confirm','Confirma la contraseña','password','','required minlength="8" autocomplete="new-password"')}`,'Guardar contraseña'));return}}
 await load();if(S.user&&!demo&&S.route==='store'){S.route='dashboard';render()}}
start();

function linkedLegacy(){return rows('legacy_customers').find(c=>c.owner_user_id===S.user?.id);}
function linkBanner(){if(isStaff())return '';const linked=linkedLegacy();return linked?`<div class="notice"><b>Historial vinculado · ${esc(linked.customer_code)}</b><p>Tus compras anteriores están disponibles en Historial anterior.</p>${btn('Ver historial','route','history','light sm')}</div>`:`<div class="notice"><b>¿Ya comprabas en 134340?</b><p>Vincula tus compras anteriores con la clave privada que te envió la administradora.</p>${btn('Vincular mi historial','claim','','soft sm')}</div>`;}
function historyTeaser(){return `<section class="panel" style="margin-top:20px"><div class="panel-head"><div><h2>Compras de la masterlist</h2><p>Consulta por separado tus registros anteriores.</p></div>${btn('Ver historial anterior','route','history','soft sm')}</div></section>`;}
function claimForm(){showModal('Vincular mis compras anteriores',form('claim',`<p>Pega la clave privada que recibiste de 134340. Se usará una sola vez y tu historial quedará unido a esta cuenta.</p>${field('key','Clave privada','text','','required maxlength="40" autocomplete="off" placeholder="XXXX-XXXX-XXXX"')}<p class="form-hint">Usa la cuenta de clienta y confirma su correo primero. No pegues aquí tu código antiguo ni la contraseña.</p>`,'Vincular historial'));}
function historyRows(records){if(!records.length)return empty('Sin registros anteriores disponibles','Si ya vinculaste tu clave, la administradora puede revisar las referencias pendientes de importar.');return records.map(r=>{const relation=r.kind==='order'?(r.source_row?`ID de pedido: ${r.source_row}`:'Sin ID de pedido registrado'):r.order_id?`Pedido relacionado: ${r.order_id}`:(r.kind==='payment'?'Sin ID de pedido individual · no se asigna a un cargo automáticamente':'Sin pedido relacionado');return `<article class="history-record"><div class="panel-head"><div><span class="eyebrow">${esc({order:'Pedido anterior',charge:'Cargo anterior',payment:'Pago anterior',shipment:'Envío anterior',warehouse:'Almacenamiento anterior',logistics:'Etapa logística anterior'}[r.kind]||'Registro anterior')}</span><h3 style="margin:7px 0">${esc(r.section||r.sheet_name)}</h3><small>${esc(r.sheet_name)} · ${r.from_sheets?'Referencia':'fila'} ${esc(r.source_row)}${r.customer_code?' · Clienta '+esc(r.customer_code):''}</small><p class="form-hint">${esc(relation)}</p></div></div><div class="history-fields">${(r.details||[]).map(d=>`<div><small>${esc(d.label)}</small><p>${esc(formatLegacyValue(d))}</p></div>`).join('')}</div></article>`}).join('');}
function formatLegacyValue(d){const s=String(d.value??'');if(/fecha/i.test(d.label)&&/^\d{5}(\.\d+)?$/.test(s)){return date(new Date(Date.UTC(1899,11,30)+Number(s)*86400000).toISOString());}return s;}
function historyPage(){const linked=linkedLegacy();const all=rows('legacy_history');const visible=isStaff()?all:(linked?all.filter(r=>r.legacy_customer_id===linked.id):[]);const kinds=[['order','Pedidos'],['charge','Cargos'],['payment','Pagos'],['shipment','Envíos'],['warehouse','Almacenamiento'],['logistics','Etapas logísticas']];const counts=Object.fromEntries(kinds.map(([k])=>[k,visible.filter(r=>r.kind===k).length]));const active=S.filter==='all'?'order':S.filter;const list=visible.filter(r=>r.kind===active&&JSON.stringify([r.sheet_name,r.section,r.source_row,r.customer_code,r.order_id,r.details]).toLowerCase().includes(S.search.toLowerCase()));const activeLabel=kinds.find(([k])=>k===active)?.[1]||'Pedidos';return `${pageHead('Historial anterior',isStaff()?'Registros anteriores organizados por tipo.':'Tus compras registradas antes de usar el portal.')}${setupError()}${S.sheetsLoaded?'<div class="notice"><b>Historial conectado a Google Sheets</b><p>Consulta cada tipo de registro por separado. Los datos originales se conservan y no generan pedidos, cargos ni movimientos nuevos.</p></div>':''}${!isStaff()&&!linked?linkBanner():''}<div class="notice"><b>Registros históricos de consulta</b><p>Pedidos, cargos, pagos, envíos, almacenamiento y etapas logísticas se muestran en apartados independientes. No se suman entre sí ni modifican saldos o existencias. Las marcas originales se conservan tal como aparecen en Sheets.</p></div><div class="chips history-tabs">${kinds.map(([k,label])=>`<button class="chip ${active===k?'active':''}" data-act="filter" data-id="${k}">${label} <span>${counts[k]}</span></button>`).join('')}</div><div class="filters"><input id="search" class="search" aria-label="Buscar en ${activeLabel}" placeholder="Buscar en ${activeLabel.toLowerCase()}…" value="${esc(S.search)}"></div><section class="panel"><div class="panel-head"><div><h2>${activeLabel}</h2><p>${list.length} registros${linked?' · '+esc(linked.customer_code):''}</p></div></div>${historyRows(list.slice(0,S.historyLimit||50))}${list.length>(S.historyLimit||50)?btn('Mostrar 50 más','history-more','','light'):''}</section>`;}
function legacyCustomersPanel(){const list=rows('legacy_customers').filter(c=>`${c.customer_code} ${c.display_name}`.toLowerCase().includes(S.search.toLowerCase()));return `<section class="panel" style="margin-top:20px"><div class="panel-head"><div><h2>Clientas de la masterlist</h2><p>${list.length} registros importados · se vinculan a una cuenta al usar su clave.</p></div>${isAdmin()?btn('Revisar importación','import-review','','light sm'):''}</div>${list.length?`<div class="table-wrap"><table><thead><tr><th>CÓDIGO</th><th>NOMBRE</th><th>VINCULACIÓN</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td><b>${esc(c.customer_code)}</b></td><td>${esc(c.display_name)}</td><td>${c.owner_user_id?'Vinculada':'Pendiente de vincular'}</td><td>${btn('Historial','legacy-customer',c.id,'light sm')}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin importación todavía','La conexión a Sheets mostrará las clientas después de actualizar.')}</section>`;}
async function showLegacyCustomer(id){if(!S.sheetsLoaded&&!demo)await loadSheetsHistory();const c=rows('legacy_customers').find(c=>c.id===id);showModal(c.customer_code+' · '+c.display_name,`<p>${c.owner_user_id?'Cuenta vinculada':'Pendiente de vincular con su clave privada.'}</p>${historyRows(rows('legacy_history').filter(r=>r.legacy_customer_id===id))}`);}
// Consulta protegida de claves privadas desde Apps Script.
async function loadPrivateKeys(){
 if(!can('customers')) throw new Error('No tienes permiso para consultar claves privadas.');
 if(demo) throw new Error('La vista previa no consulta claves reales.');
 S.privateKeysLoading=true; S.privateKeysError=''; render();
 try{const result=await sheetsRequest('private_keys');S.data.private_keys=result.keys||[];S.privateKeysLoaded=true;}
 catch(e){S.privateKeysError=errorMessage(e)||'No se pudieron consultar las claves.';}
 finally{S.privateKeysLoading=false;if(S.route==='private-keys')render();}
}
async function copyText(text){try{await navigator.clipboard.writeText(text);return}catch{}const t=document.createElement('textarea');t.value=text;t.setAttribute('readonly','');t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();const ok=document.execCommand('copy');t.remove();if(!ok)throw new Error('No se pudo copiar automáticamente. Selecciona la clave y cópiala manualmente.')}
function privateKeysPage(){
 if(!can('customers'))return empty('Acceso restringido','Necesitas permiso para consultar clientas.');
 const all=rows('private_keys');
 const q=(S.privateKeysSearch||'').trim().toLocaleLowerCase('es');
 const list=all.filter(x=>`${x.code||''} ${x.name||''} ${x.status||''}`.toLocaleLowerCase('es').includes(q));
 return `${pageHead('Claves privadas','Consulta las claves de vinculación de clientas autorizadas. Solo personal con permiso de Clientas puede verlas.',btn('Actualizar','private-keys-refresh','','light sm'))}
 <div class="notice warning"><b>Información confidencial</b><p>Estas claves permiten vincular historiales. Compártelas únicamente por mensaje privado con la clienta correspondiente. No las publiques en grupos.</p></div>
 <div class="filters"><input id="private-key-search" class="search" placeholder="Buscar por código o nombre (HA89, NA95…)" value="${esc(S.privateKeysSearch||'')}"></div>
 ${S.privateKeysLoading?'<div class="loading"><div class="loader"></div>Consultando claves…</div>':''}
 ${S.privateKeysError?`<div class="notice error"><b>No se pudieron cargar las claves</b><p>${esc(S.privateKeysError)}</p>${btn('Reintentar','private-keys-refresh','','light sm')}</div>`:''}
 <section class="panel"><div class="panel-head"><div><h2>${list.length} clientas</h2><p>Las claves se consultan directamente desde la hoja protegida.</p></div></div>
 ${list.length?`<div class="table-wrap"><table><thead><tr><th>CÓDIGO</th><th>NOMBRE</th><th>CLAVE PRIVADA</th><th>ESTADO</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td><b>${esc(x.code)}</b></td><td>${esc(x.name||'Sin nombre')}</td><td><code>${esc(x.key||'No disponible')}</code></td><td>${x.linked?'<span class="badge green">Vinculada</span>':'<span class="badge pink">Pendiente</span>'}</td><td>${x.key?btn('Copiar clave','copy-private-key',x.code,'light sm'):''}</td></tr>`).join('')}</tbody></table></div>`:(!S.privateKeysLoading&&!S.privateKeysError?empty('No hay coincidencias','Prueba con otro código o nombre.'): '')}</section>`;
}

// Masterlist completa (solo administradora): el módulo se descarga únicamente al abrir la sección.
let masterlistModule=null;
function loadMasterlistModule(){if(window.Masterlist)return Promise.resolve();return masterlistModule||(masterlistModule=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='/masterlist.js';s.async=true;s.onload=()=>window.Masterlist?resolve():(masterlistModule=null,reject(new Error('No se pudo preparar la masterlist.')));s.onerror=()=>{masterlistModule=null;s.remove();reject(new Error('No se pudo cargar la masterlist. Revisa tu conexión y vuelve a intentar.'))};document.head.appendChild(s)}));}
async function openMasterlist(){if(!isAdmin()||S.route!=='masterlist')return;S.masterlistModuleError='';try{await loadMasterlistModule();}catch(e){S.masterlistModuleError=e.message;if(S.route==='masterlist')render();return}if(S.route==='masterlist'&&isAdmin())window.Masterlist.open();}
function masterlistView(){if(!isAdmin())return empty('Acceso restringido','Solo la administradora puede consultar la masterlist completa.');try{if(window.Masterlist)return window.Masterlist.page();}catch(e){return `${pageHead('Masterlist completa','Consulta de solo lectura de la masterlist histórica.')}<div class="notice error" role="alert"><b>No se pudo mostrar la masterlist</b><p>${esc(e.message)}</p></div>`}return `${pageHead('Masterlist completa','Consulta de solo lectura de la masterlist histórica.')}${S.masterlistModuleError?`<div class="notice error" role="alert"><b>No se pudo abrir la masterlist</b><p>${esc(S.masterlistModuleError)}</p>${btn('Reintentar','route','masterlist','light sm')}</div>`:'<div class="loading" role="status"><div class="loader"></div>Cargando masterlist…</div>'}`}
